#!/usr/bin/env bash
# Imports rootfs tars as images, extracts model cache, starts the stack.
set -euo pipefail
cd "$(dirname "$0")"
# reassemble split serve rootfs if needed
if [ ! -f images/serve.rootfs.tar.gz ] && ls images/serve.rootfs.tar.gz.part-* >/dev/null 2>&1; then
  echo 'reassembling serve.rootfs.tar.gz from parts...'
  cat images/serve.rootfs.tar.gz.part-* > images/serve.rootfs.tar.gz
  echo '54be0735d411109498ccb8eaa7dc0086bb27e719d6dcd2950be0273ef2491b80  images/serve.rootfs.tar.gz' | sha256sum -c -
fi
echo 'importing serve -> docling-serve-cu126:offline'
docker import --change 'ENV VERSION=9' --change 'ENV STI_SCRIPTS_URL=image:///usr/libexec/s2i' --change 'ENV STI_SCRIPTS_PATH=/usr/libexec/s2i' --change 'ENV APP_ROOT=/opt/app-root' --change 'ENV HOME=/opt/app-root/src' --change 'ENV PLATFORM=el9' --change 'ENV NODEJS_VER=22' --change 'ENV PYTHON_VERSION=3.12' --change 'ENV PATH=/opt/app-root/src/.local/bin/:/opt/app-root/src/bin:/opt/app-root/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin' --change 'ENV PYTHONUNBUFFERED=1' --change 'ENV PYTHONIOENCODING=utf-8' --change 'ENV LC_ALL=en_US.UTF-8' --change 'ENV LANG=en_US.UTF-8' --change 'ENV PIP_NO_CACHE_DIR=off' --change 'ENV NAME=python3' --change 'ENV ARCH=x86_64' --change 'ENV SUMMARY=Platform for building and running Python 3.12 applications' --change 'ENV DESCRIPTION=Python 3.12 available as container is a base platform for building and running various Python 3.12 applications and frameworks. Python is an easy to learn, powerful programming language. It has efficient high-level data structures and a simple but effective approach to object-oriented programming. Python'"'"'s elegant syntax and dynamic typing, together with its interpreted nature, make it an ideal language for scripting and rapid application development in many areas on most platforms.' --change 'ENV BASH_ENV=/opt/app-root/bin/activate' --change 'ENV ENV=/opt/app-root/bin/activate' --change 'ENV PROMPT_COMMAND=. /opt/app-root/bin/activate' --change 'ENV TESSDATA_PREFIX=/usr/share/tesseract/tessdata/' --change 'ENV OMP_NUM_THREADS=4' --change 'ENV UV_COMPILE_BYTECODE=1' --change 'ENV UV_LINK_MODE=copy' --change 'ENV UV_PROJECT_ENVIRONMENT=/opt/app-root' --change 'ENV DOCLING_SERVE_ARTIFACTS_PATH=/opt/app-root/src/.cache/docling/models' --change 'WORKDIR /opt/app-root/src' --change 'USER 1001' --change 'EXPOSE 5001/tcp' --change 'EXPOSE 8080/tcp' --change 'LABEL com.redhat.component="python3"' --change 'LABEL description="Python 3.12 available as container is a base platform for building and running various Python 3.12 applications and frameworks. Python is an easy to learn, powerful programming language. It has efficient high-level data structures and a simple but effective approach to object-oriented programming. Python'"'"'s elegant syntax and dynamic typing, together with its interpreted nature, make it an ideal language for scripting and rapid application development in many areas on most platforms."' --change 'LABEL io.buildah.version="1.33.7"' --change 'LABEL io.k8s.description="Python 3.12 available as container is a base platform for building and running various Python 3.12 applications and frameworks. Python is an easy to learn, powerful programming language. It has efficient high-level data structures and a simple but effective approach to object-oriented programming. Python'"'"'s elegant syntax and dynamic typing, together with its interpreted nature, make it an ideal language for scripting and rapid application development in many areas on most platforms."' --change 'LABEL io.k8s.display-name="Python 3.12"' --change 'LABEL io.openshift.expose-services="8080:http"' --change 'LABEL io.openshift.s2i.scripts-url="image:///usr/libexec/s2i"' --change 'LABEL io.openshift.tags="builder,python,python312,python-312,rh-python312"' --change 'LABEL io.s2i.scripts-url="image:///usr/libexec/s2i"' --change 'LABEL maintainer="SoftwareCollections.org <sclorg@redhat.com>"' --change 'LABEL name="sclorg/python-312-c9s"' --change 'LABEL org.label-schema.build-date="20260202"' --change 'LABEL org.label-schema.license="GPLv2"' --change 'LABEL org.label-schema.name="CentOS Stream 9 Base Image"' --change 'LABEL org.label-schema.schema-version="1.0"' --change 'LABEL org.label-schema.vendor="CentOS"' --change 'LABEL org.opencontainers.image.created="2026-02-06T12:58:37.578Z"' --change 'LABEL org.opencontainers.image.description="Running Docling as an API service"' --change 'LABEL org.opencontainers.image.licenses="MIT"' --change 'LABEL org.opencontainers.image.revision="22012daf2dc254deb685941fc1f1662ca2961f58"' --change 'LABEL org.opencontainers.image.source="https://github.com/docling-project/docling-serve"' --change 'LABEL org.opencontainers.image.title="docling-serve"' --change 'LABEL org.opencontainers.image.url="https://github.com/docling-project/docling-serve"' --change 'LABEL org.opencontainers.image.version="v1.12.0"' --change 'LABEL summary="Platform for building and running Python 3.12 applications"' --change 'LABEL usage="s2i build https://github.com/sclorg/s2i-python-container.git --context-dir=3.12/test/setup-test-app/ /python3 python-sample-app"' --change 'LABEL version="9"' --change 'ENTRYPOINT ["container-entrypoint"]' --change 'CMD ["docling-serve", "run"]' images/serve.rootfs.tar.gz docling-serve-cu126:offline
echo 'importing proxy -> docling-proxy:offline'
docker import --change 'ENV PATH=/usr/local/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin' --change 'ENV LANG=C.UTF-8' --change 'ENV GPG_KEY=7169605F62C751356D054A26A821E680E5FA6305' --change 'ENV PYTHON_VERSION=3.12.14' --change 'ENV PYTHON_SHA256=5c8462af5790baf43a321a1559dbe0db06d1be4300fb85fb53c40060668e548a' --change 'WORKDIR /app' --change 'EXPOSE 5002/tcp' --change 'LABEL com.docker.compose.project="docling"' --change 'LABEL com.docker.compose.service="proxy"' --change 'LABEL com.docker.compose.version="2.24.0"' --change 'CMD ["python", "proxy_server.py"]' images/proxy.rootfs.tar.gz docling-proxy:offline
echo 'importing mcp -> docling-mcp:offline'
docker import --change 'ENV PATH=/usr/local/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin' --change 'ENV LANG=C.UTF-8' --change 'ENV GPG_KEY=7169605F62C751356D054A26A821E680E5FA6305' --change 'ENV PYTHON_VERSION=3.12.14' --change 'ENV PYTHON_SHA256=5c8462af5790baf43a321a1559dbe0db06d1be4300fb85fb53c40060668e548a' --change 'WORKDIR /app' --change 'EXPOSE 8000/tcp' --change 'CMD ["python", "mcp_server.py"]' images/mcp.rootfs.tar.gz docling-mcp:offline
echo 'extracting model cache...'
mkdir -p models
tar xzf models/docling-models-cache.tar.gz -C models
chown -R 1001:0 models/models 2>/dev/null || true
echo 'starting stack...'
docker compose -f docker-compose.offline.yml up -d
echo 'done. health: curl http://localhost:5001/health'
